fn now_or_never<F: Future>(fut: F) -> Option<F::Output> {
    let mut fut = Box::pin(fut);

    match fut.as_mut().poll(&mut Context::from_waker(Waker::noop())) {
        Poll::Ready(val) => Some(val),
        Poll::Pending => None
    }
}

